window.AUTH=window.AUTH||{};window.AUTH["19-108"]={"d":"19-108","id":"2020/19-108","n":"United States v. Briggs","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2020-01-06","url":"https://www.supremecourt.gov/DocketPDF/19/19-108/127645/20200106162031945_19-108tsUnitedStates.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondents","date":"2020-02-12","url":"https://www.supremecourt.gov/DocketPDF/19/19-108/132736/20200212100718050_Briggs%20--%20Merits%20Brief%20--%20FINAL.pdf","side":"res","n":98},{"k":"reply","label":"Reply of petitioner United States","date":"2020-03-13","url":"https://www.supremecourt.gov/DocketPDF/19/19-108/138053/20200313104102400_19-108rbUnitedStates.pdf","side":"pet","n":60}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/19-108_8njq.pdf","tr":true,"items":[{"t":"case","label":"Abdirahman v. United States","cite":"138 S. Ct. 2702","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2702/","sc":1,"by":{"0":"15"}},{"t":"case","label":"Brown v. Glines","cite":"444 U.S. 348","y":1980,"id":"1979/78-1006","sc":1,"sum":"The regulations are not invalid on their face.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Burns v. Wilson","cite":"346 U.S. 137","y":1953,"id":"scdb/1952-107","sc":1,"op":1,"sum":"Judgment affirmed. Pp. 138-146. 91 U. S. App. D. C. 208, 202 F. 2d 335, affirmed. The District Court dismissed petitioners' applications for writs of habeas corpus. 104 F. Supp. 310, 312. The Court of Appeals affirmed. 91 U. S. App. D. C. 208, 202 F. 2d 335. This Court granted certiorari. 344 U. S. 903. At the time of the argument, February 5, 1953, Wilson, present Secretary of Defense, was substituted for Lovett, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","2":"16"}},{"t":"case","label":"Chappell v. Wallace","cite":"462 U.S. 296","y":1983,"id":"1982/82-167","sc":1,"sum":"Enlisted military personnel may not maintain a suit to recover damages from a superior officer for alleged constitutional violations. The special status of the military has required, the Constitution has contemplated, Congress has created, and this Court has long recognized two systems of justice: one for civilians and one for military personnel. The need for unhesitating and decisive action by military officers and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32, 33, 35, 36","1":"34"}},{"t":"case","label":"Coker v. Georgia","cite":"433 U.S. 584","y":1977,"id":"1976/75-5444","sc":1,"op":6,"ar":24,"sum":"The Court ruled that use of the capital punishment as a penalty for rape was a form of cruel and unusual punishment forbidden by the Eighth Amendment.","sumSrc":"Oyez","by":{"0":"11, 24, 30, 36, 37","1":"passim","2":"9"}},{"t":"case","label":"Coon v. United States","cite":"411 F.2d 422","y":1969,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/411/422/","ar":1,"by":{"0":"30","1":"22, 23","2":"8"}},{"t":"case","label":"Curry v. Secretary of the Army","cite":"595 F.2d 873","y":1979,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/595/873/","by":{"0":"35"}},{"t":"case","label":"Dickey v. Florida","cite":"398 U.S. 30","y":1970,"id":"1969/728","sc":1,"sum":"On the record in this case where petitioner was at all times available to the State and there was no valid excuse for the prejudicial delay, the judgment against petitioner must be vacated by the trial court. Pp. 36-38. 215 So. 2d 772, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Doggett v. United States","cite":"505 U.S. 647","y":1992,"id":"1991/90-857","sc":1,"sum":"The Supreme Court held that the government’s egregious failure to locate and prosecute Doggett warranted relief even without showing actual prejudice. Doggett was unaware of the indictment prior to be arrested 8 ½ years later, so he could not be penalized for failing to raise the speedy trial defense earlier.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"40, 41, 42","1":"15, 41, 46","2":"21"}},{"t":"case","label":"Greer v. Spock","cite":"424 U.S. 828","y":1976,"id":"1975/74-848","sc":1,"sum":"Fort Dix, a federal military reservation devoted primarily to basic training for newly inducted Army personnel, and over which the Government exercises exclusive jurisdiction, permits free civilian access to certain unrestricted areas. However, post regulations ban speeches and demonstrations of a partisan political nature and also prohibit the distribution of literature without prior approval of post headquarters. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Jerman v. Carlisle, McNellie, Rini, Kramer & Ulrich, L.P.A.","cite":"559 U.S. 573","y":2010,"id":"2009/08-1200","sc":1,"sum":"The Court held that a debt collector's mistake in interpreting the law cannot qualify for the Fair Debt Collection Practices Act bona fide error defense.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Kahn v. Anderson","cite":"255 U.S. 1","y":1921,"id":"scdb/1920-195","sc":1,"sum":"Decided January 31, 1921,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Kennedy v. Louisiana: 554 U.S. 407, reh’g denied","cite":"554 U.S. 945","y":2008,"id":"2007/07-343","sc":1,"op":1,"sum":"The Court held that the Eighth Amendment prevented states from imposing the death penalty for the rape of a child, in which death was not intended nor resulted from the rape.","sumSrc":"Oyez","by":{"0":"35","1":"passim, 10, 33"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40, 41, 42","1":"3, 41, 46","2":"20"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Loving v. United States","cite":"517 U.S. 748","y":1996,"id":"1995/94-1966","sc":1,"sum":"The Court held that not only does the Constitution require the aggravating factors of the military's death penalty, but that the President's prescription of the challenged aggravating factors did not violate the separation-of-powers principle.","sumSrc":"Oyez","by":{"0":"31, 32","1":"33","2":"7"}},{"t":"case","label":"Martin v. Hadix","cite":"527 U.S. 343","y":1999,"id":"1998/98-262","sc":1,"sum":"The Court held that the Prison Litigation Reform Act of 1995 \"limits attorney's fees for post-judgment monitoring services performed after the PLRA's effective date, but does not limit fees for monitoring performed before that date.\" \"To impose the new standards now, for work performed before the PLRA became effective, would upset the reasonable expectations of the parties,\" Justice O'Connor wrote for the Court.","sumSrc":"Oyez","by":{"0":"40","2":"21"}},{"t":"case","label":"Middendorf v. Henry","cite":"425 U.S. 25","y":1976,"id":"1974/74-175","sc":1,"sum":"The Uniform Code of Military Justice (UCMJ) provides four methods of disposing of cases involving servicemen's offenses: general, special, and summary courts-martial, and disciplinary punishment pursuant to Art. 15 of the UCMJ. General courtsmartial and special courts-martial, which may impose substantial penalties, resemble judicial proceedings, nearly always presided over by lawyer judges, with lawyer counsel for …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Midlantic Nat’l Bank v. New Jersey Dep’t of Envtl. Prot.","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"43"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"25","1":"12, 17, 39"}},{"t":"case","label":"Ortiz v. United States","cite":"138 S. Ct. 2165","y":2018,"id":"2017/16-1423","sc":1,"op":1,"sum":"The Court held that it has jurisdiction to review the CAAF's decisions and that Judge Martin T. Mitchell’s simultaneous service on the US Court of Military Commission Review (CMCR) and the US Air Force Court of Criminal Appeals (AFCCA) does not violate the Appointments Clause or 10 U.S.C. § 973(b)(2)(A).","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Parker v. Levy","cite":"417 U.S. 733","y":1974,"id":"1973/73-206","sc":1,"sum":"Article 90 (2) of the Uniform Code of Military Justice (Code) provides for punishment of any person subject to the Code who \"willfully disobeys a lawful command of his superior commissioned officer\"; Art. 133 punishes a commissioned officer for \"conduct unbecoming an officer and a gentleman\"; and Art. 134 (the general article) punishes any person subject to the Code for, inter alia, \"all disorders and neglects to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 35, 39","2":"16"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"2019 WL 6703563","y":2019,"court":"Dec. 10","by":{"0":"26"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Schick v. Reed","cite":"419 U.S. 256","y":1974,"id":"1974/73-5677","sc":1,"sum":"Tracing the development and Court's interpretation of the President's powers to commute sentences, Chief Justice Burger argued that since the pardoning power is an enumerated one, any limit on it must be found in the Constitution. Thus, its use does not depend on statutes such as those found in the military code.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Smith v. United States","cite":"568 U.S. 106","y":2013,"id":"2012/11-8976","sc":1,"sum":"The Court held that the burden lies on the defendant, instead of the government, to prove withdrawal from a conspiracy regardless of when the withdrawal took place.","sumSrc":"Oyez","by":{"0":"25, 27, 28","2":"2"}},{"t":"case","label":"Solorio v. United States","cite":"483 U.S. 435","y":1987,"id":"1986/85-1581","sc":1,"sum":"The jurisdiction of a court-martial depends solely on the accused's status as a member of the Armed Forces, and not on the \"service connection\" of the offense charged. Thus, O'Callahanis overruled. The plain meaning of Art. I, § 8, cl. 14, of the Constitution-which grants Congress plenary power \"[t]o make Rules for the Government and Regulation of the land and naval Forces\"-supports the military status test, as was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","2":"15"}},{"t":"case","label":"Stogner v. California","cite":"539 U.S. 607","y":2003,"id":"2002/01-1757","sc":1,"sum":"The Court held that a law enacted after expiration of a previously applicable limitations period violates the Ex Post Facto Clause when it is applied to revive a previously time-barred prosecution.","sumSrc":"Oyez","by":{"0":"26, 40","1":"14, 40"}},{"t":"case","label":"Toussie v. United States","cite":"397 U.S. 112","y":1970,"id":"1969/441","sc":1,"sum":"The offense is not a continuing one but was committed by petitioner's failure to register in 1959, when the statute of limitations began to run. Pp. 114-124. 410 F. 2d 1156, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25, 27","1":"24, 25","2":"5"}},{"t":"case","label":"Trop v. Dulles","cite":"356 U.S. 86","y":1958,"id":"1956/70","sc":1,"op":1,"sum":"Expatriation of a U.S. citizen as a punishment following a general court martial is barred by the Eighth Amendment's prohibition against cruel and unusual punishment","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"United States v. Fausto","cite":"484 U.S. 439","y":1988,"id":"1987/86-595","sc":1,"sum":"The CSRA, which affords to nonpreference eligibles in the excepted service no administrative or judicial review of adverse personnel action of the type involved here, precludes judicial review for those employees under the Tucker Act based on the Back Pay Act. The CSRA was designed to replace the haphazard arrangements that had built up over almost a century with one integrated system for administrative and judicial …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"United States v. Kennedy","cite":"618 F.2d 557","y":1980,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/618/557/","by":{"0":"30","1":"23","2":"8"}},{"t":"case","label":"United States v. Kubrick","cite":"444 U.S. 111","y":1979,"id":"1979/78-1014","sc":1,"sum":"A claim accrues within the meaning of §2401 (b) when the plaintiff knows both the existence and the cause of his injury, and not at a later time when he also knows that the acts inflicting the injury may constitute medical malpractice. Hence, respondent's claim accrued in January 1969 when he was aware of his injury and its probable cause, and thus was barred by the 2-year statute of limitations.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27","2":"2"}},{"t":"case","label":"United States v. Mangahas","cite":"77 M.J. 220","y":2018,"court":"C.A.A.F.","url":"https://www.courtlistener.com/c/M.J./77/220/","op":1,"ar":4,"by":{"0":"13, 24, 30, 37","1":"passim","2":"14, 21"}},{"t":"case","label":"United States v. Marion","cite":"404 U.S. 307","y":1971,"id":"1971/70-19","sc":1,"sum":"Appellees, claiming that the Government had known of the crimes with which they were charged, the circumstances of the crimes, and appellees' identities for over three years before they were indicted, moved to dismiss on the ground that the indictment was returned \"an unreasonably oppressive and unjustifiable time after the alleged offenses,\" and that the delay deprived them of rights to due process of law and a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27","1":"2, 12, 24"}},{"t":"case","label":"United States v. Matthews","cite":"16 M.J. 354","y":1983,"court":"C.M.A.","url":"https://www.courtlistener.com/c/M.J./16/354/","by":{"0":"39","1":"13, 35, 36","2":"14"}},{"t":"case","label":"United States v. Payne","cite":"591 F.3d 46","y":2010,"url":"https://www.courtlistener.com/c/F.3d/591/46/","sum":"Observing that federal courts of appeals continue to uniformly interpret Section 3281 in the same way today.","sumSrc":"brief:0","by":{"0":"30","1":"23"}},{"t":"case","label":"United States v. Stebbins","cite":"61 M.J. 366","y":2005,"court":"C.A.A.F.","url":"https://www.courtlistener.com/c/M.J./61/366/","by":{"0":"12"}},{"t":"case","label":"Weiss v. United States","cite":"510 U.S. 163","y":1994,"id":"1993/92-1482","sc":1,"sum":"Mter courts-martial sentenced petitioners Weiss and Hernandez, United States Marines, on their pleas of guilty to offenses under the Uniform Code of Military Justice (UCMJ), their convictions were affirmed by the Navy-Marine Corps Court of Military Review in separate appeals. In affirming Weiss' conviction, the Court of Military Appeals rejected his contentions, first, that military trial and appellate judges have …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Willenbring v. Neurauter","cite":"48 M.J. 152","y":1998,"court":"C.A.A.F.","url":"https://www.courtlistener.com/c/M.J./48/152/","ar":1,"by":{"0":"10, 11, 27, 41","1":"passim","2":"20"}},{"t":"case","label":"Youngstown Sheet & Tube Co. v. Sawyer","cite":"343 U.S. 579","y":1952,"id":"1940-1955/343us579","sc":1,"sum":"The Court held that the President did not have the right to seize control of most of the country's steel mills to negate the effects of a suspected strike during the Korean War.","sumSrc":"Oyez","by":{"0":"34","2":"16"}},{"t":"law","label":"Pub. L. No. 99-661","url":"https://www.govinfo.gov/link/statute/100/3905","by":{"0":"10","1":"passim"}},{"t":"law","label":"Pub. L. No. 102-484","url":"https://www.govinfo.gov/link/statute/106/2506","by":{"0":"38","1":"11","2":"17"}},{"t":"law","label":"Pub. L. No. 104-106","url":"https://www.govinfo.gov/link/plaw/104/public/106","by":{"0":"38","2":"17"}},{"t":"law","label":"Pub. L. No. 109-163","url":"https://www.govinfo.gov/link/plaw/109/public/163","by":{"0":"8, 12","1":"passim","2":"20"}},{"t":"law","label":"Pub. L. No. 112-81","url":"https://www.govinfo.gov/link/plaw/112/public/81","by":{"0":"9"}},{"t":"law","label":"Pub. L. No. 108-375","url":"https://www.govinfo.gov/link/plaw/108/public/375","by":{"0":"42"}},{"t":"law","label":"Pub. L. No. 99-654","url":"https://www.govinfo.gov/link/statute/100/3663","by":{"0":"30","1":"29","2":"17"}},{"t":"usc","label":"10 U.S.C. § 801","url":"https://www.law.cornell.edu/uscode/text/10/801","stext":{"head":"§801. Article 1. Definitions","paras":[[0,"In this chapter (the Uniform Code of Military Justice):"],[1,"(1) The term \"Judge Advocate General\" means, severally, the Judge Advocates General of the Army, Navy, and Air Force and, except when the Coast Guard is operating as a service in the Navy, an official designated to serve as Judge Advocate General of the Coast Guard by the Secretary of Homeland Security."],[1,"(2) The Navy, the Marine Corps, and the Coast Guard when it is operating as a service in the Navy, shall be considered as one armed force."],[1,"(3) The term \"commanding officer\" includes only commissioned officers."],[1,"(4) The term \"officer in charge\" means a member of the Navy, the Marine Corps, or the Coast Guard designated as such by appropriate authority."],[1,"(5) The term \"superior commissioned officer\" means a commissioned officer superior in rank or command."],[1,"(6) The term \"cadet\" means a cadet of the United States Military Academy, the United States Air Force Academy, or the United States Coast Guard Academy."],[1,"(7) The term \"midshipman\" means a midshipman of the United States Naval Academy and any other midshipman on active duty in the naval service."],[1,"(8) The term \"military\" refers to any or all of the armed forces."],[1,"(9) The term \"accuser\" means a person who signs and swears to charges, any person who directs that charges nominally be signed and sworn to by another, and any other person who has an interest other than an official interest in the prosecution of the accused."],[1,"(10) The term \"military judge\" means a judge advocate designated under section 826(c) of this title (article 26(c)) who is detailed under section 826(a) or section 830a of this title (article 26(a) or 30a)."],[1,"(11) The term \"military magistrate\" means a commissioned officer certified for duty as a military magistrate in accordance with section 826a of this title (article 26a)."],[1,"(12) The term \"legal officer\" means any commissioned officer of the Navy, Marine Corps, or Coast Guard designated to perform legal duties for a command."],[1,"(13) The term \"judge advocate\" means—"],[2,"(A) an officer of the Judge Advocate General's Corps of the Army, the Navy, or the Air Force;"],[2,"(B) an officer of the Marine Corps who is designated as a judge advocate; or"],[2,"(C) a commissioned officer of the Coast Guard designated for special duty (law)."],[1,"(14) The term \"record\", when used in connection with the proceedings of a court-martial, means—"],[2,"(A) an official written transcript, written summary, or other writing relating to the proceedings; or"],[2,"(B) an official audiotape, videotape, or similar material from which sound, or sound and visual images, depicting the proceedings may be reproduced."],[1,"(15) The term \"classified information\" means (A) any information or material that has been determined by an official of the United States pursuant to law, an Executive order, or regulation to require protection against unauthorized disclosure for reasons of national security, and (B) any restricted data, as defined in section 11(y) of the Atomic Energy Act of 1954 (42 U.S.C. 2014(y))."],[1,"(16) The term \"national security\" means the national defense and foreign relations of the United States."],[1,"(17) The term \"covered offense\" means—"],[2,"(A) an offense under section 917a (article 117a), section 918 (article 118), section 919 (article 119), section 919a (article 119a), section 920 (article 120), section 920a (article 120a), section 920b (article 120b), section 920c (article 120c), section 925 (article 125), section 928b (article 128b), section 930 (article 130), section 932 (article 132), the standalone offense of child pornography punishable under section 934 (article 134), or the standalone offense of sexual harassment punishable under section 934 (article 134) of this title in each instance in which a formal complaint is made and such formal complaint is substantiated in accordance with regulations prescribed by the Secretary concerned;"],[2,"(B) a conspiracy to commit an offense specified in subparagraph (A) as punishable under section 881 of this title (article 81);"],[2,"(C) a solicitation to commit an offense specified in subparagraph (A) as punishable under section 882 of this title (article 82); or"],[2,"(D) an attempt to commit an offense specified in subparagraph (A), (B), or (C) as punishable under section 880 of this title (article 80)."],[1,"(18) The term \"special trial counsel\" means a judge advocate detailed as a special trial counsel in accordance with section 824a of this title (article 24a) and includes a judge advocate appointed as a lead special trial counsel pursuant to section 1044f(a)(2) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/801?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§801. Article 1. Definitions","tname":"Armed Forces","by":{"0":"10","2":"3, 4, 18"}},{"t":"usc","label":"10 U.S.C. § 818","url":"https://www.law.cornell.edu/uscode/text/10/818","subs":["(2006)"],"stext":{"head":"§818. Art. 18. Jurisdiction of general courts-martial","paras":[[0,"(a) Subject to section 817 of this title (article 17), general courts-martial have jurisdiction to try persons subject to this chapter for any offense made punishable by this chapter and may, under such limitations as the President may prescribe, adjudge any punishment not forbidden by this chapter, including the penalty of death when specifically authorized by this chapter. General courts-martial also have jurisdiction to try any person who by the law of war is subject to trial by a military tribunal and may adjudge any punishment permitted by the law of war."],[0,"(b) A general court-martial of the kind specified in section 816(b)(3) of this title (article 16(b)(3)) shall not have jurisdiction to try any person for any offense for which the death penalty may be adjudged unless the case has been previously referred to trial as a noncapital case."],[0,"(c) Consistent with sections 819 and 820 of this title (articles 19 and 20), only general courts-martial have jurisdiction over the following offenses:"],[1,"(1) A violation of subsection (a) or (b) of section 920 of this title (article 120)."],[1,"(2) A violation of subsection (a) or (b) of section 920b of this title (article 120b)."],[1,"(3) An attempt to commit an offense specified in paragraph (1) or (2) that is punishable under section 880 of this title (article 80)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/818?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§818. Art. 18. Jurisdiction of general courts-martial","tname":"Armed Forces","by":{"0":"9","2":"3, 4, 18"}},{"t":"usc","label":"10 U.S.C. § 843","url":"https://www.law.cornell.edu/uscode/text/10/843","subs":["(a)(1994)","(a)(2000)","(a)(2006)","(a)","(b)(1994)","(b)(2000)","(a)(1982)"],"stext":{"head":"§843. Art. 43. Statute of limitations","paras":[[0,"(a) No Limitation for Certain Offenses.—A person charged with absence without leave or missing movement in time of war, with murder, rape or sexual assault, or rape or sexual assault of a child, maiming of a child, kidnapping of a child, or with any other offense punishable by death, may be tried and punished at any time without limitation."],[0,"(b) Five-year Limitation for Trial by Court-martial.—(1) Except as otherwise provided in this section (article), a person charged with an offense is not liable to be tried by court-martial if the offense was committed more than five years before the receipt of sworn charges and specifications by an officer exercising summary court-martial jurisdiction over the command."],[0,"(2)(A) A person charged with having committed a child abuse offense against a child is liable to be tried by court-martial if the sworn charges and specifications are received during the life of the child or within ten years after the date on which the offense was committed, whichever provides a longer period, by an officer exercising summary court-martial jurisdiction with respect to that person."],[0,"(B) In subparagraph (A), the term \"child abuse offense\" means an act that involves abuse of a person who has not attained the age of 16 years and constitutes any of the following offenses:"],[1,"(i) Any offense in violation of section 920, 920a, 920b, 920c, or 930 of this title (article 120, 120a, 120b, 120c, or 130), unless the offense is covered by subsection (a)."],[1,"(ii) Aggravated assault, assault consummated by a battery, or assault with intent to commit specified offenses in violation of section 928 of this title (article 128)."],[0,"(C) In subparagraph (A), the term \"child abuse offense\" includes an act that involves abuse of a person who has not attained the age of 18 years and would constitute an offense under chapter 110 or 117 of title 18 or under section 1591 of that title."],[0,"(3) A person charged with an offense is not liable to be punished under section 815 of this title (article 15) if the offense was committed more than two years before the imposition of punishment."],[0,"(c) Tolling for Absence Without Leave or Flight From Justice.—Periods in which the accused is absent without authority or fleeing from justice shall be excluded in computing the period of limitation prescribed in this section (article)."],[0,"(d) Tolling for Absence From US or Military Jurisdiction.—Periods in which the accused was absent from territory in which the United States has the authority to apprehend him, or in the custody of civil authorities, or in the hands of the enemy, shall be excluded in computing the period of limitation prescribed in this article."],[0,"(e) Extension for Offenses in Time of War Detrimental to Prosecution of War.—For an offense the trial of which in time of war is certified to the President by the Secretary concerned to be detrimental to the prosecution of the war or inimical to the national security, the period of limitation prescribed in this article is extended to six months after the termination of hostilities as proclaimed by the President or by a joint resolution of Congress."],[0,"(f) Extension for Other Offenses in Time of War.—When the United States is at war, the running of any statute of limitations applicable to any offense under this chapter—"],[1,"(1) involving fraud or attempted fraud against the United States or any agency thereof in any manner, whether by conspiracy or not;"],[1,"(2) committed in connection with the acquisition, care, handling, custody, control, or disposition of any real or personal property of the United States; or"],[1,"(3) committed in connection with the negotiation, procurement, award, performance, payment, interim financing, cancellation, or other termination or settlement, of any contract, subcontract, or purchase order which is connected with or related to the prosecution of the war, or with any disposition of termination inventory by any war contractor or Government agency;"],[0,"is suspended until three years after the termination of hostilities as proclaimed by the President or by a joint resolution of Congress."],[0,"(g) Defective or Insufficient Charges.—(1) If charges or specifications are dismissed as defective or insufficient for any cause and the period prescribed by the applicable statute of limitations—"],[1,"(A) has expired; or"],[1,"(B) will expire within 180 days after the date of dismissal of the charges and specifications,"],[0,"trial and punishment under new charges and specifications are not barred by the statute of limitations if the conditions specified in paragraph (2) are met."],[0,"(2) The conditions referred to in paragraph (1) are that the new charges and specifications must—"],[1,"(A) be received by an officer exercising summary court-martial jurisdiction over the command within 180 days after the dismissal of the charges or specifications; and"],[1,"(B) allege the same acts or omissions that were alleged in the dismissed charges or specifications (or allege acts or omissions that were included in the dismissed charges or specifications)."],[0,"(h) Fraudulent Enlistment or Appointment.—A person charged with fraudulent enlistment or fraudulent appointment under section 904a(1) of this title (article 104a(1)) may be tried by court-martial if the sworn charges and specifications are received by an officer exercising summary court-martial jurisdiction with respect to that person, as follows:"],[1,"(1) In the case of an enlisted member, during the period of the enlistment or five years, whichever provides a longer period."],[1,"(2) In the case of an officer, during the period of the appointment or five years, whichever provides a longer period."],[0,"(i) DNA Evidence.—If DNA testing implicates an identified person in the commission of an offense punishable by confinement for more than one year, no statute of limitations that would otherwise preclude prosecution of the offense shall preclude such prosecution until a period of time following the implication of the person by DNA testing has elapsed that is equal to the otherwise applicable limitation period."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/843?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§843. Art. 43. Statute of limitations","tname":"Armed Forces","by":{"0":"12, 12, 12, 9, 9, 9","2":"6, 10, 11, 13, 20, 6, 1, 2, 3, 4, 6, 1, 2, 3, 4, 6, 5, 11"}},{"t":"usc","label":"10 U.S.C. § 855","url":"https://www.law.cornell.edu/uscode/text/10/855","stext":{"head":"§855. Art. 55. Cruel and unusual punishments prohibited","paras":[[0,"Punishment by flogging, or by branding, marking, or tattooing on the body, or any other cruel or unusual punishment, may not be adjudged by any court-martial or inflicted upon any person subject to this chapter. The use of irons, single or double, except for the purpose of safe custody, is prohibited."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/855?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§855. Art. 55. Cruel and unusual punishments prohibited","tname":"Armed Forces","by":{"0":"9","2":"17, 18, 19"}},{"t":"usc","label":"10 U.S.C. § 856","url":"https://www.law.cornell.edu/uscode/text/10/856","subs":["(a)"],"by":{"0":"9"}},{"t":"usc","label":"10 U.S.C. § 920","url":"https://www.law.cornell.edu/uscode/text/10/920","subs":["(a)(1982)","(a)(1994)","(a)(2000)","(a)(1)","(2000)","(b)(2000)"],"stext":{"head":"§920. Art. 120. Rape and sexual assault generally","paras":[[0,"(a) Rape.—Any person subject to this chapter who commits a sexual act upon another person by—"],[1,"(1) using unlawful force against that other person;"],[1,"(2) using force causing or likely to cause death or grievous bodily harm to any person;"],[1,"(3) threatening or placing that other person in fear that any person will be subjected to death, grievous bodily harm, or kidnapping;"],[1,"(4) first rendering that other person unconscious; or"],[1,"(5) administering to that other person by force or threat of force, or without the knowledge or consent of that person, a drug, intoxicant, or other similar substance and thereby substantially impairing the ability of that other person to appraise or control conduct;"],[0,"is guilty of rape and shall be punished as a court-martial may direct."],[0,"(b) Sexual Assault.—Any person subject to this chapter who—"],[1,"(1) commits a sexual act upon another person by—"],[2,"(A) threatening or placing that other person in fear;"],[2,"(B) making a fraudulent representation that the sexual act serves a professional purpose; or"],[2,"(C) inducing a belief by any artifice, pretense, or concealment that the person is another person;"],[1,"(2) commits a sexual act upon another person—"],[2,"(A) without the consent of the other person; or"],[2,"(B) when the person knows or reasonably should know that the other person is asleep, unconscious, or otherwise unaware that the sexual act is occurring; or"],[1,"(3) commits a sexual act upon another person when the other person is incapable of consenting to the sexual act due to—"],[2,"(A) impairment by any drug, intoxicant, or other similar substance, and that condition is known or reasonably should be known by the person; or"],[2,"(B) a mental disease or defect, or physical disability, and that condition is known or reasonably should be known by the person;"],[0,"is guilty of sexual assault and shall be punished as a court-martial may direct."],[0,"(c) Aggravated Sexual Contact.—Any person subject to this chapter who commits or causes sexual contact upon or by another person, if to do so would violate subsection (a) (rape) had the sexual contact been a sexual act, is guilty of aggravated sexual contact and shall be punished as a court-martial may direct."],[0,"(d) Abusive Sexual Contact.—Any person subject to this chapter who commits or causes sexual contact upon or by another person, if to do so would violate subsection (b) (sexual assault) had the sexual contact been a sexual act, is guilty of abusive sexual contact and shall be punished as a court-martial may direct."],[0,"(e) Proof of Threat.—In a prosecution under this section, in proving that a person made a threat, it need not be proven that the person actually intended to carry out the threat or had the ability to carry out the threat."],[0,"(f) Defenses.—An accused may raise any applicable defenses available under this chapter or the Rules for Court-Martial. Marriage is not a defense for any conduct in issue in any prosecution under this section."],[0,"(g) Definitions.—In this section:"],[1,"(1) Sexual act.—The term \"sexual act\" means—"],[2,"(A) the penetration, however slight, of the penis into the vulva or anus or mouth;"],[2,"(B) contact between the mouth and the penis, vulva, scrotum, or anus; or"],[2,"(C) the penetration, however slight, of the vulva or penis or anus of another by any part of the body or any object, with an intent to abuse, humiliate, harass, or degrade any person or to arouse or gratify the sexual desire of any person."],[1,"(2) Sexual contact.—The term \"sexual contact\" means touching, or causing another person to touch, either directly or through the clothing, the vulva, penis, scrotum, anus, groin, breast, inner thigh, or buttocks of any person, with an intent to abuse, humiliate, harass, or degrade any person or to arouse or gratify the sexual desire of any person. Touching may be accomplished by any part of the body or an object."],[1,"(3) Grievous bodily harm.—The term \"grievous bodily harm\" means serious bodily injury. It includes fractured or dislocated bones, deep cuts, torn members of the body, serious damage to internal organs, and other severe bodily injuries. It does not include minor injuries such as a black eye or a bloody nose."],[1,"(4) Force.—The term \"force\" means—"],[2,"(A) the use of a weapon;"],[2,"(B) the use of such physical strength or violence as is sufficient to overcome, restrain, or injure a person; or"],[2,"(C) inflicting physical harm sufficient to coerce or compel submission by the victim."],[1,"(5) Unlawful force.—The term \"unlawful force\" means an act of force done without legal justification or excuse."],[1,"(6) Threatening or placing that other person in fear.—The term \"threatening or placing that other person in fear\" means a communication or action that is of sufficient consequence to cause a reasonable fear that non-compliance will result in the victim or another person being subjected to the wrongful action contemplated by the communication or action."],[1,"(7) Consent.—"],[2,"(A) The term \"consent\" means a freely given agreement to the conduct at issue by a competent person. An expression of lack of consent through words or conduct means there is no consent. Lack of verbal or physical resistance does not constitute consent. Submission resulting from the use of force, threat of force, or placing another person in fear also does not constitute consent. A current or previous dating or social or sexual relationship by itself or the manner of dress of the person involved with the accused in the conduct at issue does not constitute consent."],[2,"(B) A sleeping, unconscious, or incompetent person cannot consent. A person cannot consent to force causing or likely to cause death or grievous bodily harm or to being rendered unconscious. A person cannot consent while under threat or in fear or under the circumstances described in subparagraph (B) or (C) of subsection (b)(1)."],[2,"(C) All the surrounding circumstances are to be considered in determining whether a person gave consent."],[1,"(8) Incapable of consenting.—The term \"incapable of consenting\" means the person is—"],[2,"(A) incapable of appraising the nature of the conduct at issue; or"],[2,"(B) physically incapable of declining participation in, or communicating unwillingess to engage in, the sexual act at issue."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/920?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§920. Art. 120. Rape and sexual assault generally","tname":"Armed Forces","by":{"0":"11, 28, 28, 28","2":"11, 1, 2, 3, 1, 2, 3, 11"}},{"t":"usc","label":"18 U.S.C. § 3281","url":"https://www.law.cornell.edu/uscode/text/18/3281","stext":{"head":"§3281. Capital offenses","paras":[[0,"An indictment for any offense punishable by death may be found at any time without limitation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3281?type=usc&year=mostrecent&link-type=html"},"head":"§3281. Capital offenses","tname":"Crimes and Criminal Procedure","by":{"0":"28","2":"4, 8, 9, 10"}},{"t":"usc","label":"18 U.S.C. § 3299","url":"https://www.law.cornell.edu/uscode/text/18/3299","stext":{"head":"§3299. Child abduction and sex offenses","paras":[[0,"Notwithstanding any other law, an indictment may be found or an information instituted at any time without limitation for any offense under section 1201 involving a minor victim, and for any felony under chapter 109A, 110 (except for section 1 2257 and 2257A), or 117, or section 1591."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3299?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3299. Child abduction and sex offenses","tname":"Crimes and Criminal Procedure","by":{"0":"28"}},{"t":"reg","label":"3 C.F.R. pt. 156","url":"https://www.ecfr.gov/current/title-3/part-156","by":{"0":"8"}},{"t":"reg","label":"3 C.F.R. pt. 201","url":"https://www.ecfr.gov/current/title-3/part-201","by":{"0":"8"}},{"t":"reg","label":"3 C.F.R. pt. 243","url":"https://www.ecfr.gov/current/title-3/part-243","by":{"0":"9"}},{"t":"reg","label":"3 C.F.R. pt. 510","url":"https://www.ecfr.gov/current/title-3/part-510","by":{"0":"9"}},{"t":"case","label":"Am. Tobacco Co. v. Patterson","cite":"456 U.S. 63","y":1982,"id":"1981/80-1199","sc":1,"sum":"The Court held that the absence of any sort of grandfather clause or explicit distinction between pre- and post-Act systems meant that the section applied to all seniority systems, regardless of when they were put in place. There was no clear legislative history to support the distinction between pre-existing systems and those that were implemented later.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Ashwander v. TVA","cite":"297 U.S. 288","y":1936,"id":"1900-1940/297us288","sc":1,"sum":"The Court held that Congress did not abuse its power with the TVA. Justice Hughes argued that the Wilson Dam, the location where the TVA was in the business of generating electricity, had been built originally in the interest of national defense: it produced materials involved in munitions manufacture. The government could sell excess electricity to consumers without violating the Constitution.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Atkins v. Virginia","cite":"536 U.S. 304","y":2002,"id":"2001/00-8452","sc":1,"op":3,"ar":1,"sum":"The Court found that sentencing a mentally disabled person to death is a violation of the Eighth Amendment's Cruel and Unusual Punishment Clause.","sumSrc":"Oyez","by":{"1":"31","2":"13"}},{"t":"case","label":"BedRoc Ltd., LLC v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"sum":"The Court ruled that because sand and gravel were not commercially valuable in 1919 when the Pittman Act was passed, they were not \"valuable minerals\" covered under the Act.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of the Fed. Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2012,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"BP Am. Prod. Co. v. Burton","cite":"549 U.S. 84","y":2006,"id":"2006/05-669","sc":1,"sum":"The Court ruled 7-0 that \"the 6-year statute of limitations in 2415(a) applies only to court actions and not to the administrative proceedings involved in this case.\" The opinion by Justice Samuel Alito relied on the plain meaning of the language in Section 2415(a). The statute used the terms \"action\" and \"complaint\" when referring to the statute of limitations.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Bridges v. United States","cite":"346 U.S. 209","y":1953,"id":"scdb/1952-109","sc":1,"sum":"The general three-year statute of limitations, 18 U. S. C. (Supp. V), § 3282, is applicable to each of the offenses charged, and the indictment came too late.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 24"}},{"t":"case","label":"Brockett v. Spokane Arcades, Inc.","cite":"472 U.S. 491","y":1985,"id":"1984/84-28","sc":1,"sum":"The Court of Appeals erred in facially invalidating the statute in its entirety.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Church of Scientology of Cal. v. IRS","cite":"484 U.S. 9","y":1987,"id":"1987/86-472","sc":1,"sum":"The Haskell Amendment does not exempt from § 6103(b)(2)'s definition of confidential \"return information\" material in IRS files which can be redacted to delete those parts which would identify a particular taxpayer. If the mere removal of identifying details sufficed to put the information \"in a form\" envisioned by the Amendment, the remainder of the protected categories of information included in §6103(b)(2) would …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Cleveland v. United States","cite":"531 U.S. 12","y":2000,"id":"2000/99-804","sc":1,"sum":"The Court held that State and municipal licenses in general, and Louisiana's video poker licenses in particular, do not rank as \"property,\" for purposes of federal law, in the hands of the official licensor.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"138 S. Ct. 1612","y":2018,"id":"2017/16-285","sc":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"20","2":"18"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"139 S. Ct. 2356","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"3, 19"}},{"t":"case","label":"Furman v. Georgia","cite":"408 U.S. 238","y":1972,"id":"1971/69-5030","sc":1,"sum":"The Court found that the death penalty constituted cruel and unusual punishment in the case of an accidental burglary death.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Gregg v. Georgia","cite":"428 U.S. 153","y":1976,"id":"1975/74-6257","sc":1,"sum":"The Court ruled that the death penalty was not \"cruel and unusual\" punishment in violation of the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Griffith v. Kentucky","cite":"479 U.S. 314","y":1987,"id":"1986/85-5221","sc":1,"sum":"The Court held that after a new rule had been decided in a particular case, \"the integrity of judicial review requires that we apply that rule to all similar cases pending on direct review.\" The Court reasoned that selective application of new rules violated the principle of treating similarly situated defendants on an equal basis.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Hamling v. United States","cite":"418 U.S. 87","y":1974,"id":"1973/73-507","sc":1,"sum":"Petitioners were convicted of mailing and conspiring to mail an obscene advertising brochure with sexually explicit photographic material relating to their illustrated version (hereafter Illustrated Report) of an official report on obscenity, in violation of 18 U. S. C. §§ 2, 371, and 1461. The indictment under § 1461 charged petitioners in the language of the statute, which provides in pertinent part that obscene …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Hardt v. Reliance Standard Life Ins. Co.","cite":"560 U.S. 242","y":2010,"id":"2009/09-448","sc":1,"sum":"The Court held that a party is entitled to attorneys' fees pursuant to Section 502(g)(1) of the Employee Retirement Income Security Act when an ERISA violation has occurred.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Jam v. Int’l Fin. Corp.","cite":"139 S. Ct. 759","y":2019,"id":"2018/17-1011","sc":1,"sum":"The International Organizations Immunities Act of 1945 affords international organizations the same immunity from suit that foreign governments enjoy today under the Foreign Sovereign Immunities Act of 1976.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"18"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"Jones v. R.R. Donnelley & Sons Co.","cite":"541 U.S. 369","y":2004,"id":"2003/02-1205","sc":1,"sum":"It also applies to amendments of previously existing laws. Writing for a unanimous Court, Justice John Paul Stevens stated \"[a]n amendment to an existing statute is no less an 'Act of Congress' than a new, stand-alone statute.\" The four-year statute of limitations therefore applies to any act or amendment to an act passed by Congress after 1990.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Kellogg Brown & Root Servs., Inc. v. United States ex rel. Carter","cite":"135 S. Ct. 1970","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1970/","sc":1,"by":{"1":"24","2":"13"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"sum":"The Court held that the 1996 version of the federal habeas statute, as to standards affecting the entitlement of state prisoners to federal habeas corpus relief, does not to apply to non-capital habeas corpus cases that were pending when the Act was enacted.","sumSrc":"Oyez","by":{"1":"15, 41, 45"}},{"t":"case","label":"Marks v. United States","cite":"430 U.S. 188","y":1977,"id":"1976/75-708","sc":1,"sum":"The Due Process Clause of the Fifth Amendment precludes retroactive application to petitioners of the Miller standards, to the extent that those standards may impose criminal liability for conduct not punishable under the standards announced in Memoirs v. Massachusetts, 383 U. S. 413. Bouie v. City of Columbia, 378 U. S. 347. Specifically, petitioners are entitled to jury instructions requiring the jury to acquit …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"3"}},{"t":"case","label":"Miller v. California","cite":"413 U.S. 15","y":1973,"id":"1971/70-73","sc":1,"sum":"The Court found that \"obscene materials\" do not have First Amendment protection.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Milner v. Dep’t of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Parker Drilling Mgmt. Servs., Ltd. v. Newton","cite":"139 S. Ct. 1881","y":2019,"id":"2018/18-389","sc":1,"sum":"Under the Outer Continental Shelf Lands Act, where federal law addresses the relevant issue, state law is not adopted as surrogate federal law on the Outer Continental Shelf.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"21"}},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"sum":"Bribery of private employees prohibited by state criminal statutes violates the Travel Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 18"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Reino v. State","cite":"352 So.2d 853","y":1977,"court":"Fla.","url":"https://www.courtlistener.com/c/So.2d/352/853/","by":{"1":"2, 12, 18"}},{"t":"case","label":"Roper v. Simmons","cite":"543 U.S. 551","y":2005,"id":"2004/03-633","sc":1,"op":2,"sum":"The Court held that executing minors under the death penalty is unconstitutional.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Ross v. Blake","cite":"136 S. Ct. 1850","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"17","2":"3"}},{"t":"case","label":"Sandifer v. U.S. Steel Corp.","cite":"571 U.S. 220","y":2014,"id":"2013/12-417","sc":1,"sum":"The Court held that putting on safety garments constitutes \"changing clothes\" under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Schrader v. Holder","cite":"704 F.3d 980","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/704/980/","by":{"1":"12, 18"}},{"t":"case","label":"Shannon v. United States","cite":"512 U.S. 573","y":1994,"id":"1993/92-8346","sc":1,"sum":"The city's dedication requirements constitute an uncompensated taking of property.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"6"}},{"t":"case","label":"Sullivan v. Finkelstein","cite":"496 U.S. 617","y":1990,"id":"1989/89-504","sc":1,"sum":"The Secretary may immediately appeal a district court order effectively invalidating regulations limiting the kinds of inquiries that must be made to determine entitlement to disability insurance benefits and remanding a claim to the Secretary for consideration without those restrictions. Pp. 623-631. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Taniguchi v. Kan Pac. Saipan, Ltd.","cite":"566 U.S. 560","y":2012,"id":"2011/10-1472","sc":1,"sum":"The Court held that the winner of a federal-court lawsuit cannot be reimbursed by the losing party for any document translation costs under 28 U.S.C. § 1920(6).","sumSrc":"Oyez","by":{"1":"11"}},{"t":"case","label":"Thorpe v. Housing Auth. of Durham","cite":"393 U.S. 268","y":1969,"id":"1968/20","sc":1,"sum":"The Court also decided that the circular was mandatory, not advisory, and it was not an unconstitutional impairment of the Housing Authorities lease agreement. Justice Hugo L. Black wrote a special concurrence stating that because the Housing Authority admitted to following the circular nothing needed to be decided other than that the circular applied in this case.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"United States v. Armbruster","cite":"29 C.M.R. 412","y":1960,"url":"https://www.courtlistener.com/c/C.M.R./29/412/","by":{"1":"35"}},{"t":"case","label":"United States v. Avila","cite":"53 M.J. 99","y":2000,"court":"C.A.A.F.","url":"https://www.courtlistener.com/c/M.J./53/99/","by":{"1":"37"}},{"t":"case","label":"United States v. Clark","cite":"18 M.J. 775","y":1984,"court":"N-M.C.M.R.","url":"https://www.courtlistener.com/c/M.J./18/775/","by":{"1":"33"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"United States v. Habig","cite":"390 U.S. 222","y":1968,"id":"1967/107","sc":1,"sum":"Where allegedly false tax returns were filed after the statutory due date (extensions having been granted), the applicable statute of limitations (26 U. S. C. § 6531) held to run from the dates the alleged offenses were committed, i. e., the dates on which the returns were filed, not from the statutory due date. Pp. 224-227. 270 F. Supp. 929, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"United States v. Hickson","cite":"22 M.J. 146","y":1986,"court":"C.M.A.","url":"https://www.courtlistener.com/c/M.J./22/146/","by":{"1":"32"}},{"t":"case","label":"United States v. Martinez","cite":"19 M.J. 744","y":1984,"court":"C.M.R.","url":"https://www.courtlistener.com/c/M.J./19/744/","by":{"1":"37"}},{"t":"case","label":"United States v. McReynolds","cite":"9 M.J. 881","y":1980,"court":"A.F.C.M.R.","url":"https://www.courtlistener.com/c/M.J./9/881/","by":{"1":"33"}},{"t":"case","label":"United States v. Pope","cite":"392 U.S. 651","y":1968,"id":"1967/34_misc","sc":1,"sum":"Certiorari granted; 372 F. 2d 710, vacated and remanded. Wallace M. Rudolph for petitioner. Solicitor General Griswold, Assistant Attorney General Vinson, Ralph S. Spritzer, Beatrice Rosenberg, and, Jerome M. Feit for the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"United States v. Pub. Util. Comm’n of Cal.","cite":"345 U.S. 295","y":1953,"id":"scdb/1952-073","sc":1,"sum":"The rates for such sales of power for resale are subject to regulation by the Federal Power Commission under Part II of the Federal Power Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"United States v. Scharton","cite":"285 U.S. 518","y":1932,"id":"scdb/1931-055","sc":1,"sum":"Section 1110 (a) of the Revenue Act of 1926 sets a general limitation of three years upon the prosecution of \" any of the various offenses arising under the internal revenue laws... Provided, That for offenses involving the defrauding or attempting to defraud the United States... in any manner, the period of limitation shall be six years....\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"United States v. Sharpnack","cite":"355 U.S. 286","y":1958,"id":"1957/35","sc":1,"sum":"The Assimilative Crimes Act of 1948, 18 U. S. C. § 13, is constitutional insofar as it makes applicable to a federal enclave a subsequently enacted criminal law of the State in which the enclave is situated. Pp. 286-297. Reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"United States v. Universal C.I.T. Credit Corp.","cite":"344 U.S. 218","y":1952,"id":"scdb/1952-026","sc":1,"sum":"The order of the District Court is affirmed without prejudice to amendment of the information.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"United States v. Wappler","cite":"9 C.M.R. 23","y":1953,"url":"https://www.courtlistener.com/c/C.M.R./9/23/","ar":2,"by":{"1":"13, 37"}},{"t":"case","label":"Vartelas v. Holder","cite":"566 U.S. 257","y":2012,"id":"2011/10-1211","sc":1,"sum":"The Court held that 8 U.S.C. § 1101(a)(13)(C)(v) cannot be applied retroactively to a lawful permanent resident who pleads guilty to a crime prior to the effective date of the Illegal Immigration Reform and Immigrant Responsibility Act.","sumSrc":"Oyez","by":{"1":"43, 46"}},{"t":"case","label":"Weems v. United States","cite":"217 U.S. 349","y":1910,"id":"scdb/1909-139","sc":1,"ar":1,"sum":"A paramount governmental authority may make use of subordinate governmental instruments, without the creation of a distinct legal entity as is the case of the United States and the United States Government of the Philippine Islands.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31"}},{"t":"case","label":"Wis. Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"1":"25","2":"18"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"1":"passim","2":"4, 5, 12, 17, 19"}},{"t":"usc","label":"10 U.S.C. § 815","url":"https://www.law.cornell.edu/uscode/text/10/815","by":{"1":"14, 38"}},{"t":"usc","label":"18 U.S.C. § 2031","url":"https://www.law.cornell.edu/uscode/text/18/2031","by":{"1":"34"}},{"t":"usc","label":"21 U.S.C. § 849","url":"https://www.law.cornell.edu/uscode/text/21/849","subs":["(b)(1)"],"stext":{"head":"§849. Transportation safety offenses","paras":[[0,"(a) Definitions"],[0,"In this section—"],[1,"\"safety rest area\" means a roadside facility with parking facilities for the rest or other needs of motorists."],[1,"\"truck stop\" means a facility (including any parking lot appurtenant thereto) that—"],[2,"(A) has the capacity to provide fuel or service, or both, to any commercial motor vehicle (as defined in section 31301 of title 49), operating in commerce (as defined in that section); and"],[2,"(B) is located within 2,500 feet of the National System of Interstate and Defense Highways or the Federal-Aid Primary System."],[0,"(b) First offense"],[0,"A person who violates section 841(a)(1) of this title or section 856 of this title by distributing or possessing with intent to distribute a controlled substance in or on, or within 1,000 feet of, a truck stop or safety rest area is (except as provided in subsection (b)) 1 subject to—"],[1,"(1) twice the maximum punishment authorized by section 841(b) of this title; and"],[1,"(2) twice any term of supervised release authorized by section 841(b) of this title for a first offense."],[0,"(c) Subsequent offense"],[0,"A person who violates section 841(a)(1) of this title or section 856 of this title by distributing or possessing with intent to distribute a controlled substance in or on, or within 1,000 feet of, a truck stop or a safety rest area after a prior conviction or convictions under subsection (a) 2 have become final is subject to—"],[1,"(1) 3 times the maximum punishment authorized by section 841(b) of this title; and"],[1,"(2) 3 times any term of supervised release authorized by section 841(b) of this title for a first offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/849?type=usc&year=mostrecent&link-type=html"},"head":"§849. Transportation safety offenses","tname":"Food and Drugs","by":{"1":"18","2":"4"}},{"t":"usc","label":"28 U.S.C. § 1259","url":"https://www.law.cornell.edu/uscode/text/28/1259","by":{"1":"5, 6"}},{"t":"law","label":"Pub. L. No. 109-248","url":"https://www.govinfo.gov/link/plaw/109/public/248","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 99-145","url":"https://www.govinfo.gov/link/statute/99/583","by":{"1":"8"}},{"t":"law","label":"Pub. L. No. 114-328","url":"https://www.govinfo.gov/link/plaw/114/public/328","by":{"1":"42"}},{"t":"law","label":"Pub. L. No. 113-66","url":"https://www.govinfo.gov/link/plaw/113/public/66","by":{"1":"9"}},{"t":"case","label":"Briefs and Legal Transcripts Transcript of Oral Argument, CBOCS West, Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Brief for the United States in Opposition, Andrews v. United States","cite":"513 U.S. 1057","y":1994,"url":"https://supreme.justia.com/cases/federal/us/513/1057/","sc":1,"by":{"1":"6"}},{"t":"case","label":"Brief for the United States in Opposition, Colon v. United States","cite":"502 U.S. 821","y":1991,"url":"https://supreme.justia.com/cases/federal/us/502/821/","sc":1,"by":{"1":"6"}},{"t":"case","label":"Brief for the United States in Opposition, Larrabee v. United States","cite":"139 S. Ct. 1164","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/1164/","sc":1,"by":{"1":"5"}},{"t":"case","label":"Brief for the United States in Opposition, McKeel v. United States","cite":"549 U.S. 1019","y":2006,"url":"https://supreme.justia.com/cases/federal/us/549/1019/","sc":1,"by":{"1":"6"}},{"t":"case","label":"Brief for the United States in Opposition, Stevenson v. United States","cite":"555 U.S. 816","y":2008,"url":"https://supreme.justia.com/cases/federal/us/555/816/","sc":1,"by":{"1":"5"}},{"t":"case","label":"Brief for the United States in Opposition, Sullivan v. United States","cite":"137 S. Ct. 31","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./137/31/","sc":1,"by":{"1":"38"}},{"t":"case","label":"Brief for the United States in Opposition, Wiechmann v. United States","cite":"559 U.S. 904","y":2010,"url":"https://supreme.justia.com/cases/federal/us/559/904/","sc":1,"by":{"1":"5"}},{"t":"case","label":"Blanton v. City of North Las Vegas","cite":"489 U.S. 538","y":1989,"id":"1988/87-1437","sc":1,"sum":"There is no Sixth Amendment right to a trial by jury for persons charged under Nevada law with DUI. This Court has long held that petty crimes or offenses are not subject to the Sixth Amendment jury trial provision. The most relevant criterion for determining the seriousness of an offense is the severity of the maximum authorized penalty fixed by the legislature. Under this approach, when an offense carries a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"op":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Fitzpatrick v. United States","cite":"178 U.S. 304","y":1900,"id":"scdb/1899-063","sc":1,"sum":"Under the Court of Appeals Act of March 3, 1891, a conviction for murder is a “conviction of a capital crime,” though the jury qualify their verdict of guilty by adding the words “ without capital punishment.” The test of a capital crime is not the punishment which is imposed, but that which maybe imposed under the statute.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith, Inc. v. Curran","cite":"456 U.S. 353","y":1982,"id":"1981/80-203","sc":1,"sum":"A private party may maintain an action for damages caused by a violation of the CEA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Microsoft Corp. v. I4I Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Shular v. United States","cite":"2020 WL 908904","y":2020,"court":"Feb. 26","by":{"2":"12"}},{"t":"case","label":"United States v. Bennett","cite":"21 C.M.R. 223","y":1956,"court":"C.M.A.","url":"https://www.courtlistener.com/c/C.M.R./21/223/","by":{"2":"14"}},{"t":"case","label":"United States v. Gallaher","cite":"624 F.3d 934","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/624/934/","by":{"2":"9"}},{"t":"case","label":"United States v. Whittle","cite":"133 F.3d 919","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/133/919/","sum":"Concluding that a rape committed in 1982 was “punishable by death” and could therefore be prosecuted in 1996.","sumSrc":"brief:2","by":{"2":"9"}},{"t":"law","label":"Pub. L. No. 108-136","url":"https://www.govinfo.gov/link/plaw/108/public/136","by":{"2":"11"}},{"t":"usc","label":"10 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/10/853","subs":["(c)(2)"],"by":{"2":"4"}},{"t":"usc","label":"10 U.S.C. § 886","url":"https://www.law.cornell.edu/uscode/text/10/886","subs":["(1994)"],"by":{"2":"6, 18"}},{"t":"usc","label":"10 U.S.C. § 887","url":"https://www.law.cornell.edu/uscode/text/10/887","subs":["(1994)"],"by":{"2":"6"}},{"t":"usc","label":"10 U.S.C. § 906","url":"https://www.law.cornell.edu/uscode/text/10/906","stext":{"head":"§906. Art. 106. Impersonation of officer, noncommissioned or petty officer, or agent or official","paras":[[0,"(a) In General.—Any person subject to this chapter who, wrongfully and willfully, impersonates—"],[1,"(1) an officer, a noncommissioned officer, or a petty officer;"],[1,"(2) an agent of superior authority of one of the armed forces; or"],[1,"(3) an official of a government;"],[0,"shall be punished as a court-martial may direct."],[0,"(b) Impersonation With Intent to Defraud.—Any person subject to this chapter who, wrongfully, willfully, and with intent to defraud, impersonates any person referred to in paragraph (1), (2), or (3) of subsection (a) shall be punished as a court-martial may direct."],[0,"(c) Impersonation of Government Official Without Intent to Defraud.—Any person subject to this chapter who, wrongfully, willfully, and without intent to defraud, impersonates an official of a government by committing an act that exercises or asserts the authority of the office that the person claims to have shall be punished as a court-martial may direct."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/906?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§906. Art. 106. Impersonation of officer, noncommissioned or petty officer, or agent or official","tname":"Armed Forces","by":{"2":"18"}},{"t":"usc","label":"10 U.S.C. § 910","url":"https://www.law.cornell.edu/uscode/text/10/910","by":{"2":"18"}},{"t":"usc","label":"18 U.S.C. § 3148","url":"https://www.law.cornell.edu/uscode/text/18/3148","subs":["(1976)"],"by":{"2":"8"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(b)"],"by":{"2":"4"}}]};